sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var weights = {
        "Pre-K": 1,
        "JK": 1,
        "SK": 1,
        "1": 0.75,
        "2": 0.5,
        "3": 0.5,
        "4": 0.5,
        "5": 0.5,
        "6": 0.5,
        "7": 0.5,
        "8": 0.5,
        "9": 0.5,
        "10": 0.5,
        "11": 0.5,
        "12": 0.5
    };
    var scoreTSA = 0;

    //Single choice questions
    function addSingle(field, table, factor = 1) {
        var id = current.getValue(field);
        if (!id) return;
        scoreTSA += (table[id] || 0) * factor;
    }

    //Multiple choice questions
    function addMulti(field, table, factor = 1) {
        var raw = current.getValue(field);
        if (!raw) return;
        raw.split(',').forEach(function(id) {
            id = id.trim();
            scoreTSA += (table[id] || 0) * factor;
        });
    }

    //Communication sociale - 0.225
    //l_l_ve_prouve_t_il_des_difficult_s_li_es_explication - multiple choice
    var weights_comm_soc_1 = {
        "924a840f1b45ca508d594047bc4bcbf1": 15,
        "124a840f1b45ca508d594047bc4bcbf2": 15,
        "164a840f1b45ca508d594047bc4bcbf2": 15,
        "21369369470ee2106274efbb616d43c0": 0,
    };
    addMulti('l_l_ve_prouve_t_il_des_difficult_s_li_es_explication', weights_comm_soc_1, 0.225);

    //l_l_ve_prouve_t_il_des_difficult_s_r_guler_les_interactions_sociales_en_util - multiple choice
    var weights_comm_soc_2 = {
        "a22b044f1b45ca508d594047bc4bcba9": 15,
        "622b444f1b45ca508d594047bc4bcb64": 15,
        "662b444f1b45ca508d594047bc4bcb64": 10,
        "6a2b444f1b45ca508d594047bc4bcb64": 10,
        "6e2b444f1b45ca508d594047bc4bcb64": 15,
        "622b444f1b45ca508d594047bc4bcb65": 8,
        "1f8f5fa5474ee2106274efbb616d43ea": 0,
    };
    addMulti('l_l_ve_prouve_t_il_des_difficult_s_r_guler_les_interactions_sociales_en_util', weights_comm_soc_2, 0.225);

    //l_l_ve_d_montre_t_il_de_l_int_r_t_partager_son_plaisir_ses_r_ussites_et_ses (conditional) - multiple choice
    var weights_comm_soc_3 = {
        "c18b884f1b45ca508d594047bc4bcbda": 12,
        "498b884f1b45ca508d594047bc4bcbda": 10,
        "4d8b884f1b45ca508d594047bc4bcbda": 8,
        "418b884f1b45ca508d594047bc4bcbdb": 8,
        "7ba763a1478ee2106274efbb616d4356": 6,
        "d8c76f61478ee2106274efbb616d43b2": 5,
        "01d7a761478ee2106274efbb616d4324": 4,
    };
    addMulti('l_l_ve_d_montre_t_il_de_l_int_r_t_partager_son_plaisir_ses_r_ussites_et_ses', weights_comm_soc_3, 0.225);

    //l_l_ve_prouve_t_il_des_difficult_s_former_des_relations_avec_ses_pairs_du_m (conditional) - multiple choice
    var weights_comm_soc_4 = {
        "94dbcc4f1b45ca508d594047bc4bcb84": 15,
        "1cdbcc4f1b45ca508d594047bc4bcb84": 12,
        "10dbcc4f1b45ca508d594047bc4bcb85": 10,
        "4107e47147c226106274efbb616d4329": 8,
    };
    addMulti('l_l_ve_prouve_t_il_des_difficult_s_former_des_relations_avec_ses_pairs_du_m', weights_comm_soc_4, 0.225);

	gs.info("score 0.225:" + scoreTSA);

    //Compréhension langagière - 0.1
    //l_l_ve_d_montre_t_il_des_difficult_s_comprendre_le_langage_oral_explication (conditional) - multiple choice
    var weights_comp_lang = {
        "efcaa4f547c226106274efbb616d4385": 7,
        "92fa68f547c226106274efbb616d4338": 8,
        "7c1b68f547c226106274efbb616d43b3": 3,
        "264b203947c226106274efbb616d43ca": 9,
        "cc6b203947c226106274efbb616d4305": 3,
    };
    addMulti('l_l_ve_d_montre_t_il_des_difficult_s_comprendre_le_langage_oral_explication', weights_comp_lang, 0.1);

	gs.info("score 0.1:" + scoreTSA);

    //Habiletés expressives - 0.05
    //les_enfants_utilisent_souvent_plus_d_un_moyen_pour_exprimer_leurs_besoins - single choice
    var weights_hab_exp = {
        "914e243d47c226106274efbb616d430f": 30,
        "2b5eecf947c226106274efbb616d430e": 15,
        "fe6eecf947c226106274efbb616d43a3": 7,
        "6ace643d47c226106274efbb616d43c0": 0,
    };
    addSingle('les_enfants_utilisent_souvent_plus_d_un_moyen_pour_exprimer_leurs_besoins', weights_hab_exp, 0.05);

	gs.info("score 0.05:" + scoreTSA);

    //Routines/flexibilité - 0.3
    //difficult_s_au_niveau_de_la_routine_et_des_transitions (conditional) - multiple choice
    var weights_rout_flex = {
        "f4ce8c031b85ca508d594047bc4bcbd1": 22,
        "70ce8c031b85ca508d594047bc4bcbd2": 22,
        "74ce8c031b85ca508d594047bc4bcbd2": 22,
    };
    addMulti('difficult_s_au_niveau_de_la_routine_et_des_transitions', weights_rout_flex, 0.3);

	gs.info("score 0.3:" + scoreTSA);

    //Jeu - 0.175
    //l_l_ve_pr_sente_t_il_des_difficult_s_au_niveau_des_habilet_s_li_es_au_jeu_ex (conditional) - single choice
    var weights_jeu = {
        "b93d34fd470626106274efbb616d43e6": 90,
        "d24d74fd470626106274efbb616d43d2": 60,
        "7e5db4fd470626106274efbb616d434e": 40,
        "316db0fd470626106274efbb616d439c": 0,
    };
    addSingle('l_l_ve_pr_sente_t_il_des_difficult_s_au_niveau_des_habilet_s_li_es_au_jeu_ex', weights_jeu, 0.175);

	gs.info("score 0.175:" + scoreTSA);

    //Imitation - 0.15
    //l_l_ve_prouve_t_il_des_difficult_s_imiter (conditional) - single choice
    var weights_imitation = {
        "6f2fb4b1474626106274efbb616d4392": 80,
        "a23ff4b1474626106274efbb616d431c": 55,
        "0091c5b1474626106274efbb616d43b2": 20,
        "5aa105b1474626106274efbb616d4301": 5,
    };
    addSingle('l_l_ve_prouve_t_il_des_difficult_s_imiter', weights_imitation, 0.15);

	gs.info("score 0.15:" + scoreTSA);

	var level = current.eleve.u_classe.name;
	scoreTSA = scoreTSA * weights[level];
	gs.info("scoreFinal :" + scoreTSA);
	current.setValue('scoretsa', parseFloat(scoreTSA.toFixed(1)));
	current.update();

})(current, previous);
